      "crm-30Actor",
      "crm-30Result"
    ]
  },
  {
    "name": "CrmAudit30",
    "fields": [
      "crm-30EventId",
      "crm-30Reviewer",
      "crm-30Decision",
      "crm-30CreatedAt"
    ]
  }
] as const;
export const relationships = [
  {
    "from": "CrmRuntime30",
    "to": "CrmEvent30",
    "type": "one-to-many",
    "via": "crm-30RecordId"
  },
  {
    "from": "CrmEvent30",
    "to": "CrmAudit30",
    "type": "one-to-many",
    "via": "crm-30EventId"
  }
] as const;

export function assertRelationalSchema() {
  if (relationships.length < 2) throw new Error("Relational schema is required.");
  return relationships.map((relation) => relation.from + " -> " + relation.to);
}

import { applyClientsMutation, removeClientsRecord, transitionClientsRecord } from "@/lib/pipeline-engine";

export const statusFlow = [
  "Lead",
  "In Progress",
  "Review",
  "Done"
] as const;

export function handleClientsAction(records: Array<{ id: string; label: string; value: string; status: string; meta?: string; parentId?: string }>, body: { action?: string; id?: string; label?: string; value?: string; status?: string }) {
  if (body.action === "transition" && body.id) return transitionClientsRecord(records, body.id, [...statusFlow]);
  if (body.action === "delete" && body.id) return removeClientsRecord(records, body.id);
  return applyClientsMutation(records, { label: body.label || "Create crm event", value: body.value || "New", status: body.status || statusFlow[0] || "Created" });
}

